const raw = $input.first().json.stdout
const lines = raw.split('\n').filter(Boolean);
const result = { already_connected: 'false', public_key: '' };

for (const line of lines) {
  if (line.startsWith('already_connected=')) {
    result.already_connected = line.replace('already_connected=', '').trim();
  }
  if (line.startsWith('public_key=')) {
    result.public_key = line.replace('public_key=', '').trim();
  }
}

result.destination_host =$('Load Backup Configuration').first().json.remoteHost


return [{ json: result }];

const form = $('When Backup Setup Form Submitted').item.json;

function fail(msg) {
  throw new Error(`Invalid input: ${msg}`);
}

// Absolute Linux path, only letters/digits/-/_/./  — no spaces, quotes, $, backticks, ; | & etc.
const SAFE_PATH_RE = /^\/[A-Za-z0-9_\-./]*$/;

// Valid hostname (RFC1123)
const SAFE_HOSTNAME_RE = /^(?=.{1,253}$)(?!-)[A-Za-z0-9-]{1,63}(?<!-)(\.(?!-)[A-Za-z0-9-]{1,63}(?<!-))*$/;

// Dangerous characters for the passphrase (it gets embedded inside a double-quoted shell string)
const UNSAFE_PASSPHRASE_RE = /["'`$\\;|&<>\n\r]/;

// --- Backup mode ---
const modeLabel = form['Backup mode'] || '';
const ALLOWED_MODES = ['Versioned backups', 'Sync (Only one backup at a time)'];
if (!ALLOWED_MODES.includes(modeLabel)) fail('Invalid "Backup mode" value.');
const mode = modeLabel.toLowerCase().includes('sync') ? 'sync' : 'versioned';

// --- Encrypted ---
const encryptLabel = form['Encrypt the backup?'] || '';
const ALLOWED_ENCRYPT = ['Yes (recommended)', 'No'];
if (!ALLOWED_ENCRYPT.includes(encryptLabel)) fail('Invalid "Encrypt the backup?" value.');
const encrypted = encryptLabel.startsWith('Yes');

// --- Source directory ---
const sourceDir = (form['Source directory on the server'] || '').trim();
if (!SAFE_PATH_RE.test(sourceDir)) {
  fail('"Source directory" must be an absolute Linux path containing only letters, digits, "-", "_", "." and "/" (no spaces, quotes, $, backticks, ;, | etc.).');
}

// --- Destination directory (created under the borg_backup user's home) ---
const destDir = (form['Destination directory on the second server'] || '').trim();
if (!SAFE_PATH_RE.test(destDir)) {
  fail('"Destination directory" must start with "/" and contain only letters, digits, "-", "_", "." and "/".');
}

// --- Remote host (IPv4 or hostname) ---
const remoteHost = (form['Second server host or IP'] || '').trim();
const octets = remoteHost.split('.');
const isIPv4 = octets.length === 4 && octets.every(o => /^\d{1,3}$/.test(o) && Number(o) <= 255);
if (!isIPv4 && !SAFE_HOSTNAME_RE.test(remoteHost)) {
  fail('"Second server host or IP" must be a valid IPv4 address or hostname.');
}

// --- Remote port ---
const rawPort = form['Second server SSH port'];
const remotePort = rawPort === undefined || rawPort === '' ? 22 : Number(rawPort);
if (!Number.isInteger(remotePort) || remotePort < 1 || remotePort > 65535) {
  fail('"Second server SSH port" must be an integer between 1 and 65535.');
}

// --- Borg passphrase ---
const borgPassphrase = form['Borg encryption passphrase'] || '';
if (encrypted) {
  if (!borgPassphrase) fail('"Borg encryption passphrase" is required when encryption is enabled.');
  if (UNSAFE_PASSPHRASE_RE.test(borgPassphrase)) {
    fail('"Borg encryption passphrase" must not contain the characters " \' ` $ \\ ; | & < > or newlines.');
  }
  if (borgPassphrase.length > 256) fail('"Borg encryption passphrase" is too long.');
}

const config = {
  sourceDir,
  destDir,
  mode,
  encrypted,
  remoteHost,
  remotePort,
};

return [{
  json: {
    config,
    borgPassphrase
  }
}];
